-- ============================================================
-- Table: review_reason_summary
-- NOTE: This table is NOT created by SQL. It is generated by the
--       Python reason-classifier: python/reason_analysis_v2.py
--
-- Purpose: Rule-based, negation-aware classification of each
--          Portuguese review into actionable reasons (late delivery,
--          damaged item, wrong item, refund request, praise themes...).
--          Stores reason × sentiment counts + % of that sentiment.
-- Feeds:   Power BI "Voice of Customer" page
--
-- To regenerate:
--   set OLIST_DB_PASSWORD=<password>
--   python python/reason_analysis_v2.py
--
-- Schema (for reference):
--   sentiment_label   VARCHAR(10)   -- negative / neutral / positive
--   reason            VARCHAR(60)   -- e.g. 'Late or non-delivery'
--   review_count      INT           -- # reviews of that sentiment matching
--   pct_of_sentiment  DECIMAL(5,1)  -- share of that sentiment's reviews
--   pct_label         VARCHAR(10)   -- pre-formatted display string e.g. '33.3%'
-- ============================================================